const csrf=document.querySelector('meta[name="csrf-token"]').content;
const icons={dashboard:'<rect x="3" y="3" width="8" height="8" rx="1"/><rect x="13" y="3" width="8" height="5" rx="1"/><rect x="13" y="10" width="8" height="11" rx="1"/><rect x="3" y="13" width="8" height="8" rx="1"/>',wilayah:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6zM9 3v15M15 6v15"/>',cuaca:'<path d="M12 2v2M4 12H2M5.3 5.3l1.4 1.4M18.7 5.3l-1.4 1.4"/><circle cx="12" cy="11" r="4"/><path d="M8 21h10a4 4 0 0 0 0-8h-2"/>',iklim:'<path d="M12 22a8 8 0 0 0 8-8c0-4-8-12-8-12S4 10 4 14a8 8 0 0 0 8 8z"/>',sinkronisasi:'<path d="M3 12a9 9 0 0 1 15-6l3 3M21 12a9 9 0 0 1-15 6l-3-3M21 3v6h-6M3 21v-6h6"/>',berita:'<path d="M4 4h14v16H4zM18 8h3v10a2 2 0 0 1-2 2M7 8h8M7 12h8M7 16h4"/>',aktivitas:'<path d="M4 20h16M8 16l4-12 4 12M6 16h12"/>',pengaturan:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>'};
const pages=[['dashboard','Dashboard','Monitoring keseluruhan data dan sistem CERAH.'],['wilayah','Data Wilayah','Periksa cakupan dan status pembaruan wilayah.'],['cuaca','Cuaca Terkini','Pantau kelengkapan kondisi cuaca wilayah.'],['iklim','Histori Iklim','Validasi indikator hujan dan Hari Tanpa Hujan.'],['sinkronisasi','Sinkronisasi','Tinjau log proses dan jalankan sinkronisasi manual.'],['berita','Manajemen Berita','Tinjau dan atur publikasi berita.'],['aktivitas','Saran Aktivitas','Lihat delapan jenis aktivitas CERAH.'],['pengaturan','Pengaturan','Jadwal dan konfigurasi sistem.']];
const activities=['Penyeberangan Pompong','Nelayan Tradisional & Kelong','Penjemuran Hasil Laut','Penerbangan Bandara RHF','Kuliner Tepi Laut','Olahraga & Rekreasi','Pertanian Sayur Lokal','Perjalanan Darat & Berkendara'];
let D=null,current='dashboard',toastTimer=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('id-ID').format(n);
const icon=id=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]}</svg>`;
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('on'),4200)}
async function api(url,opts={}){const r=await fetch(url,{...opts,headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,'Content-Type':'application/json',...(opts.headers||{})}});if(r.status===401||r.status===419){location.href=LOGIN_URL;throw new Error('Sesi berakhir')}const j=await r.json().catch(()=>({}));if(!r.ok&&!j.message)j.message='Permintaan gagal ('+r.status+')';return {ok:r.ok&&j.ok!==false,json:j}}
async function load(manual){try{const {json}=await api(DATA_URL);D=json;render();if(manual)toast('Data dimuat ulang.')}catch(e){toast('Gagal memuat data: '+e.message)}}
async function runCommand(key,btn){const out=document.getElementById('run-output');const old=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Memproses… (bisa beberapa menit)'}toast('Proses dimulai. Jangan tutup halaman.');try{const {ok,json}=await api(RUN_URL,{method:'POST',body:JSON.stringify({command:key})});toast(json.message||(ok?'Selesai.':'Gagal.'));if(out&&json.output){out.style.display='block';out.textContent=json.output}}catch(e){toast('Gagal: '+e.message)}finally{if(btn){btn.disabled=false;btn.textContent=old}load()}}
async function toggleNews(id){const {json}=await api(NEWS_URL+'/'+id+'/toggle',{method:'POST',body:'{}'});const n=D.news.find(x=>x.id===id);if(n){n.hidden=json.hidden;D.news_visible+=json.hidden?-1:1}render();toast(json.hidden?'Artikel disembunyikan dari website.':'Artikel ditampilkan di website.')}
function navigate(id){current=id;document.querySelectorAll('.section-view').forEach(x=>x.classList.toggle('active',x.id==='v-'+id));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.id===id));const p=pages.find(x=>x[0]===id);document.getElementById('page-title').textContent=p[1]==='Dashboard'?'Dashboard Admin':p[1];document.getElementById('page-subtitle').textContent=p[2];document.getElementById('bread').textContent=p[1];window.scrollTo({top:0,behavior:'smooth'});history.replaceState(null,'','#'+id)}
function renderNav(){document.getElementById('nav').innerHTML=pages.map(([id,name])=>`<button type="button" data-id="${id}" title="${name}" onclick="navigate('${id}')">${icon(id)}<span>${name}</span></button>`).join('')}
function kpi(title,value,note,ic,cls=''){return `<div class="card kpi"><div class="kpi-top"><span>${title}</span><span class="kpi-ic ${cls}">${icon(ic)}</span></div><strong>${value}</strong><div class="kpi-note ${cls==='green'?'good':cls==='amber'?'warn':''}">${note}</div></div>`}
const dash=v=>v===null||v===undefined?'—':v;
function table(list){if(!list.length)return '<div class="empty">Tidak ada data.</div>';return `<table class="table"><thead><tr><th>Kode</th><th>Wilayah</th><th>Cuaca</th><th>Suhu</th><th>Kelembapan</th><th>AQI</th><th>Update</th></tr></thead><tbody>${list.map(r=>`<tr><td style="color:#89a0b1">${esc(r.code)}</td><td class="strong">${esc(r.name)}</td><td><span class="pill ${r.weather===null?'red':''}">${esc(r.weather??'Belum ada data')}</span></td><td>${r.temp===null?'—':r.temp+'°C'}</td><td>${r.humidity===null?'—':r.humidity+'%'}</td><td>${dash(r.aqi)}</td><td>${r.updated?esc(r.updated)+' WIB':'—'}</td></tr>`).join('')}</tbody></table>`}
function logs(){if(!D.logs.length)return '<div class="empty">Belum ada log proses.</div>';return D.logs.map(l=>`<div class="log"><div class="log-icon ${l.status==='fail'?'red':l.status==='partial'?'warn':''}">${l.status==='success'?'✓':'!'}</div><div class="log-text"><b>${esc(l.name)}</b><small>${esc(l.desc)}</small></div><div class="log-time">${esc(l.time)}</div></div>`).join('')}
function render(){if(!D)return;const q=D.quality,failed=D.last_weather?D.last_weather.failed:0,missing=q.total-q.weather;
 document.getElementById('gen-time').textContent=D.generated_at;
 document.getElementById('kpis').innerHTML=kpi('Total Wilayah',fmt(q.total),'Kabupaten/kota hingga kelurahan','wilayah')+kpi('Cuaca Terkini',fmt(q.weather),missing?fmt(missing)+' wilayah belum ada data':'Semua wilayah terisi','cuaca',missing?'amber':'green')+kpi('Riwayat Iklim',fmt(D.climate.rows),'Baris data harian tersimpan','iklim')+kpi('Berita Aktif',fmt(D.news_visible),'Artikel tampil di website','berita');
 const top=D.regions.filter(r=>r.top);
 document.getElementById('weather-table-home').innerHTML=table(top.slice(0,6));document.getElementById('weather-table-detail').innerHTML=table(top);
 document.getElementById('logs-home').innerHTML=logs();document.getElementById('logs-full').innerHTML=logs();
 document.getElementById('quality-bars').innerHTML=[['Cuaca terkini tersedia',q.weather,q.total,missing?'amber':'green'],['Suhu tersedia',q.temperature,q.total,'green'],['Kelembapan tersedia',q.humidity,q.total,''],['AQI tersedia',q.aqi,q.total,'amber']].map(([label,n,total,color])=>`<div><div class="status-line"><span>${label}</span><b>${fmt(n)} / ${fmt(total)}</b></div><div class="bar"><span class="${color}" style="width:${total?(n/total*100).toFixed(1):0}%"></span></div></div>`).join('');
 document.getElementById('weather-kpis').innerHTML=kpi('Total Wilayah',fmt(q.total),'Cakupan data target','wilayah')+kpi('Suhu Terisi',fmt(q.temperature),fmt(q.total-q.temperature)+' belum tersedia','cuaca',q.temperature<q.total?'amber':'green')+kpi('Kelembapan Terisi',fmt(q.humidity),fmt(q.total-q.humidity)+' belum tersedia','iklim',q.humidity<q.total?'amber':'green')+kpi('AQI Terisi',fmt(q.aqi),fmt(q.total-q.aqi)+' belum tersedia','cuaca',q.aqi<q.total?'amber':'green');
 const c=D.climate;
 document.getElementById('climate-kpis').innerHTML=kpi('Periode','30 hari',esc(c.from)+' s.d. '+esc(c.to),'iklim')+kpi('Rata-rata HTH',c.avg_dry_days+' hari','Per wilayah · tidak berurutan','cuaca')+kpi('Curah Hujan',String(c.avg_rain_mm).replace('.',',')+' mm','Rata-rata akumulasi per wilayah','iklim')+kpi('Cakupan Data',c.coverage+'%',fmt(c.regions)+' wilayah punya data','wilayah',c.coverage<90?'amber':'green');
 const max=Math.max(1,...c.daily.map(d=>d.value));
 document.getElementById('climate-bars').innerHTML=c.daily.length?c.daily.map(d=>`<div class="bar-item" title="${esc(d.date)}: ${d.value} mm"><div class="stick" style="height:${Math.max(4,d.value/max*120)}px"></div><small>${esc(d.date)}</small></div>`).join(''):'<div class="empty" style="width:100%">Belum ada data iklim 30 hari.</div>';
 document.getElementById('sync-kpis').innerHTML=kpi('Wilayah Diproses',D.last_weather?fmt(D.last_weather.processed):'—','Sinkronisasi cuaca terakhir','wilayah')+kpi('Cuaca Terisi',fmt(q.weather),'Wilayah punya data terkini','cuaca','green')+kpi('Gagal',D.last_weather?fmt(failed):'—','Pada sinkronisasi terakhir','sinkronisasi',failed?'amber':'green')+kpi('Jadwal','6 jam','Sinkronisasi cuaca penuh (WIB)','iklim');
 document.getElementById('activity-table').innerHTML=`<table class="table"><thead><tr><th>No</th><th>Jenis Aktivitas</th><th>Pengaturan Saran</th><th>Status</th></tr></thead><tbody>${activities.map((a,i)=>`<tr><td>${i+1}</td><td class="strong">${esc(a)}</td><td>Berdasarkan kondisi cuaca</td><td><span class="pill green">Aktif</span></td></tr>`).join('')}</tbody></table>`;
 document.getElementById('news-list').innerHTML=D.news.length?D.news.map(n=>`<div class="article"><div><h3>${esc(n.title)}</h3><p><a href="${esc(n.url)}" target="_blank" rel="noreferrer" style="color:#2175b7">Buka sumber ↗</a></p><small>${esc(n.source)} · ${esc(n.published)}${n.hidden?' · <b style="color:#be635b">Disembunyikan</b>':''}</small></div><button class="btn ${n.hidden?'primary':''}" onclick="toggleNews(${n.id})">${n.hidden?'Tampilkan':'Sembunyikan'}</button></div>`).join(''):'<div class="empty">Belum ada artikel berita.</div>';
 renderRegions();renderChart()}
function renderRegions(){if(!D)return;const q=(document.getElementById('region-search').value||'').toLowerCase().trim();const all=D.regions.filter(r=>!q||r.code.includes(q)||r.name.toLowerCase().includes(q));const shown=all.slice(0,200);document.getElementById('weather-table').innerHTML=all.length?table(shown)+(all.length>shown.length?`<p class="footnote" style="padding:0 14px">Menampilkan 200 dari ${fmt(all.length)} wilayah. Persempit pencarian untuk melihat lainnya.</p>`:''):'<div class="empty">Wilayah tidak ditemukan.</div>'}
function renderChart(){const v=D.weekly.map(x=>x.value),max=Math.max(1,...v);const y=n=>177-(n/max)*150;const grid=[0,1,2,3].map(i=>`<line x1="30" y1="${24+i*47}" x2="650" y2="${24+i*47}" stroke="#e5eef5" stroke-width="1"/>`).join('');const pts=v.map((n,i)=>`${48+i*96},${y(n)}`).join(' ');const dots=v.map((n,i)=>`<circle cx="${48+i*96}" cy="${y(n)}" r="4.5" fill="#2888c1" stroke="#fff" stroke-width="3"/>`).join('');const labels=D.weekly.map((d,i)=>`<text x="${48+i*96}" y="205" text-anchor="middle" font-size="11" fill="#8aa0b2">${esc(d.label)}</text>`).join('');document.getElementById('weekly-chart').innerHTML=`<svg viewBox="0 0 680 218" preserveAspectRatio="none" role="img" aria-label="Grafik jumlah wilayah berhasil tujuh hari">${grid}<polygon points="48,177 ${pts} 624,177" fill="#65b8e6" opacity=".1"/><polyline points="${pts}" fill="none" stroke="#2888c1" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${dots}${labels}<text x="16" y="27" font-size="10" fill="#8aa0b2">${fmt(max)}</text><text x="16" y="171" font-size="10" fill="#8aa0b2">0</text></svg>`}
renderNav();navigate((location.hash||'#dashboard').slice(1).replace(/[^a-z]/g,'')&&pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard');load();setInterval(()=>{if(!document.hidden)load()},120000);
</script>
</body></html>